    if ((fl_flags & (1u << 4)) != 0) { out.native_params = tl::read_boxed<tl::DataJSON>(rv); }
    if ((fl_flags & (1u << 6)) != 0) { out.additional_methods = tl::read_vector<std::shared_ptr<tl::PaymentFormMethod>>(rv, [&](TlReader& r472) -> std::shared_ptr<tl::PaymentFormMethod> { return tl::read_boxed<tl::PaymentFormMethod>(r472); }); }
    if ((fl_flags & (1u << 0)) != 0) { out.saved_info = tl::read_boxed<tl::PaymentRequestedInfo>(rv); }
    if ((fl_flags & (1u << 1)) != 0) { out.saved_credentials = tl::read_vector<std::shared_ptr<tl::PaymentSavedCredentials>>(rv, [&](TlReader& r473) -> std::shared_ptr<tl::PaymentSavedCredentials> { return tl::read_boxed<tl::PaymentSavedCredentials>(r473); }); }
    out.users = tl::read_vector<std::shared_ptr<tl::User>>(rv, [&](TlReader& r474) -> std::shared_ptr<tl::User> { return tl::read_boxed<tl::User>(r474); });
    return out;
